#!/bin/bash
# gen-defconfigs.sh — assemble the Buildroot defconfigs from the shared base
# and the per-board deltas.
#
#   configs/base.config              shared selections (one source of truth)
#   configs/boards/<board>.config    board delta, appended after the base
#   configs/rnsbox_<board>_defconfig generated file (committed, never edited)
#
# Usage:
#   scripts/gen-defconfigs.sh           regenerate every defconfig
#   scripts/gen-defconfigs.sh --check   fail if any generated file is stale
#
# The delta wins over the base for any symbol it mentions: the assembler
# drops the base's assignment for those symbols before appending the delta,
# so the generated file has no duplicate assignments.  --check is wired into
# build.sh and CI, so editing a delta (or the base) without regenerating
# fails loudly instead of shipping a stale image config.
set -eu

HERE="$(cd "$(dirname "$(readlink -f "$0")")" && pwd)"
ROOT="$(cd "$HERE/.." && pwd)"
BASE="$ROOT/configs/base.config"
BOARDS="$ROOT/configs/boards"
MODE="${1:-}"

case "$MODE" in
    ""|--check) ;;
    *) echo "usage: $0 [--check]" >&2; exit 1 ;;
esac

[ -f "$BASE" ] || { echo "FATAL: missing $BASE" >&2; exit 1; }
[ -d "$BOARDS" ] || { echo "FATAL: missing $BOARDS" >&2; exit 1; }

tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT
bad=0

# rnsbox_<name>_defconfig <-> configs/boards/<name>.config
for delta in "$BOARDS"/*.config; do
    if [ ! -f "$delta" ]; then
        echo "FATAL: no board deltas in $BOARDS" >&2
        exit 1
    fi

    name="$(basename "$delta" .config)"
    out="$ROOT/configs/rnsbox_${name}_defconfig"

    # Symbols the delta defines; their base assignment is superseded.
    syms="$(sed -n -e 's/^\(BR2_[A-Za-z0-9_]*\)=.*/\1/p' \
                     -e 's/^# \(BR2_[A-Za-z0-9_]*\) is not set$/\1/p' \
                     "$delta" | sort -u)"
    if [ -n "$syms" ]; then
        pat="$(printf '%s\n' "$syms" | tr '\n' '|' | sed 's/|$//')"
        base_body="$(grep -vE "^(${pat})=|^# (${pat}) is not set$" "$BASE" || true)"
    else
        base_body="$(cat "$BASE")"
    fi

    {
        echo "# Generated by scripts/gen-defconfigs.sh — do not edit."
        echo "# Sources: configs/base.config + configs/boards/${name}.config"
        echo
        printf '%s\n' "$base_body"
        echo
        cat "$delta"
    } > "$tmp"

    if [ "$MODE" = "--check" ]; then
        if ! cmp -s "$tmp" "$out"; then
            echo "stale: $out (run scripts/gen-defconfigs.sh)" >&2
            bad=1
        fi
    else
        chmod 0644 "$tmp"
        mv -f "$tmp" "$out"
        tmp="$(mktemp)"
        trap 'rm -f "$tmp"' EXIT
    fi
done

# A generated defconfig without a delta is an orphan: the next board should
# be added as configs/boards/<name>.config, not as a hand-written defconfig.
for out in "$ROOT"/configs/rnsbox_*_defconfig; do
    [ -f "$out" ] || continue
    name="${out##*/rnsbox_}"
    name="${name%_defconfig}"
    if [ ! -f "$BOARDS/$name.config" ]; then
        echo "orphan: $out has no configs/boards/$name.config" >&2
        bad=1
    fi
done

if [ "$bad" -ne 0 ]; then
    exit 1
fi
[ "$MODE" = "--check" ] && echo ">> generated defconfigs are current"
exit 0
